begin;
create schema if not exists orbit_private;
revoke all on schema orbit_private from public;
grant usage on schema orbit_private to anon, authenticated, service_role;
create table public.orbit_profiles (id uuid primary key references auth.users(id) on delete cascade,handle text unique not null check(handle ~ '^[a-z][a-z0-9_]{2,23}$'),display_name text not null check(length(display_name) between 1 and 80),bio text not null default '' check(length(bio)<=500),university text not null default '' check(length(university)<=100),campus text not null default '' check(length(campus)<=100),created_at timestamptz not null default now());
alter table public.orbit_profiles enable row level security;
create table public.orbit_circles (id bigint generated by default as identity primary key,title text not null check(length(title) between 1 and 60),description text not null check(length(description) between 1 and 240),owner uuid not null references public.orbit_profiles(id),private boolean not null default false,rules text not null default '' check(length(rules)<=2000));
alter table public.orbit_circles enable row level security;
create table public.orbit_members (circle bigint references public.orbit_circles(id) on delete cascade,actor uuid references public.orbit_profiles(id) on delete cascade,role text not null default 'member' check(role in ('owner','moderator','member')),primary key(circle,actor));
alter table public.orbit_members enable row level security;
create table public.orbit_join_requests (circle bigint references public.orbit_circles(id) on delete cascade,actor uuid references public.orbit_profiles(id) on delete cascade,primary key(circle,actor));
alter table public.orbit_join_requests enable row level security;
create table public.orbit_posts (id bigint generated by default as identity primary key,author uuid not null references public.orbit_profiles(id),title text not null check(length(title) between 1 and 180),text text not null check(length(text) between 1 and 4000),topic text not null default '' check(length(topic)<=50),circle bigint references public.orbit_circles(id),created timestamptz not null default now(),edited timestamptz,deleted boolean not null default false,upvotes integer not null default 0 check(upvotes>=0),reply_count integer not null default 0 check(reply_count>=0));
alter table public.orbit_posts enable row level security;
create table public.orbit_comments (id bigint generated by default as identity primary key,post bigint not null references public.orbit_posts(id),author uuid not null references public.orbit_profiles(id),parent bigint references public.orbit_comments(id),text text not null check(length(text) between 1 and 2000),created timestamptz not null default now(),edited timestamptz,deleted boolean not null default false);
alter table public.orbit_comments enable row level security;
create table public.orbit_votes (post bigint references public.orbit_posts(id) on delete cascade,actor uuid references public.orbit_profiles(id) on delete cascade,primary key(post,actor));
alter table public.orbit_votes enable row level security;
create table public.orbit_follows (actor uuid references public.orbit_profiles(id) on delete cascade,target uuid references public.orbit_profiles(id) on delete cascade,primary key(actor,target),check(actor<>target));
alter table public.orbit_follows enable row level security;
create table public.orbit_connections (sender uuid not null references public.orbit_profiles(id),recipient uuid not null references public.orbit_profiles(id),status text not null check(status in ('pending','accepted','declined','removed')),low_actor uuid generated always as (least(sender,recipient)) stored,high_actor uuid generated always as (greatest(sender,recipient)) stored,primary key(low_actor,high_actor),check(sender<>recipient));
alter table public.orbit_connections enable row level security;
create table public.orbit_blocks (actor uuid references public.orbit_profiles(id) on delete cascade,target uuid references public.orbit_profiles(id) on delete cascade,primary key(actor,target),check(actor<>target));
alter table public.orbit_blocks enable row level security;
create table public.orbit_messages (id bigint generated by default as identity primary key,sender uuid not null references public.orbit_profiles(id),recipient uuid not null references public.orbit_profiles(id),text text not null check(length(text) between 1 and 2000),created timestamptz not null default now());
alter table public.orbit_messages enable row level security;
create table public.orbit_games (id bigint generated by default as identity primary key,low_actor uuid not null references public.orbit_profiles(id),high_actor uuid not null references public.orbit_profiles(id),game jsonb not null check(jsonb_typeof(game)='object'),status text not null check(status in ('invited','active','won','draw','declined','cancelled','resigned','expired')),version integer not null default 1 check(version>0),updated_at timestamptz not null default now(),check(low_actor<high_actor));
alter table public.orbit_games enable row level security;
create table public.orbit_notifications (id bigint generated by default as identity primary key,actor uuid not null references public.orbit_profiles(id),sender uuid not null references public.orbit_profiles(id),kind text not null,ref bigint,created timestamptz not null default now(),read boolean not null default false);
alter table public.orbit_notifications enable row level security;
create table public.orbit_reports (id bigint generated by default as identity primary key,reporter uuid not null references public.orbit_profiles(id),target uuid not null references public.orbit_profiles(id),reason text not null check(reason in ('Spam','Harassment','Impersonation','Other')),details text not null default '' check(length(details)<=1000),status text not null default 'open' check(status in ('open','reviewed','resolved')),created timestamptz not null default now());
alter table public.orbit_reports enable row level security;
create index orbit_members_0_idx on public.orbit_members(actor,circle);
create index orbit_join_requests_0_idx on public.orbit_join_requests(actor,circle);
create index orbit_posts_0_idx on public.orbit_posts(author,id desc);
create index orbit_posts_1_idx on public.orbit_posts(circle,id desc);
create index orbit_comments_0_idx on public.orbit_comments(post,id desc);
create index orbit_comments_1_idx on public.orbit_comments(author,id desc);
create index orbit_comments_2_idx on public.orbit_comments(parent);
create index orbit_votes_0_idx on public.orbit_votes(actor,post);
create index orbit_follows_0_idx on public.orbit_follows(target,actor);
create index orbit_connections_0_idx on public.orbit_connections(sender,status);
create index orbit_connections_1_idx on public.orbit_connections(recipient,status);
create index orbit_blocks_0_idx on public.orbit_blocks(target,actor);
create index orbit_messages_0_idx on public.orbit_messages(sender,recipient,id desc);
create index orbit_messages_1_idx on public.orbit_messages(recipient,sender,id desc);
create index orbit_games_0_idx on public.orbit_games(low_actor,high_actor,id desc);
create index orbit_notifications_0_idx on public.orbit_notifications(actor,id desc);
create index orbit_notifications_1_idx on public.orbit_notifications(sender);
create index orbit_reports_0_idx on public.orbit_reports(reporter,id desc);
create index orbit_reports_1_idx on public.orbit_reports(target);
create index orbit_posts_feed_idx on public.orbit_posts(id desc) where not deleted;
create unique index orbit_one_unfinished_game_idx on public.orbit_games(low_actor,high_actor) where status in ('invited','active');
create table orbit_private.moderators(actor uuid primary key references public.orbit_profiles(id) on delete cascade);
create table orbit_private.write_limits(actor uuid primary key references public.orbit_profiles(id) on delete cascade,bucket timestamptz not null default date_trunc('minute',now()),count integer not null default 0);
alter table orbit_private.moderators enable row level security;
alter table orbit_private.write_limits enable row level security;
create function orbit_private.actor() returns uuid language plpgsql stable security definer set search_path='' as $$
declare u uuid:=auth.uid();begin if u is null or not exists(select 1 from auth.users where id=u and email_confirmed_at is not null) then raise exception 'Sign in with a verified email first.' using errcode='42501';end if;return u;end;$$;
create function orbit_private.blocked(a uuid,b uuid) returns boolean language sql stable security definer set search_path='' as $$select a is not null and b is not null and (a=auth.uid() or b=auth.uid()) and exists(select 1 from public.orbit_blocks where (actor=a and target=b) or (actor=b and target=a));$$;
create function orbit_private.member(c bigint) returns boolean language sql stable security definer set search_path='' as $$select auth.uid() is not null and exists(select 1 from public.orbit_members where circle=c and actor=auth.uid());$$;
create function orbit_private.circle_mod(c bigint) returns boolean language sql stable security definer set search_path='' as $$select auth.uid() is not null and exists(select 1 from public.orbit_members where circle=c and actor=auth.uid() and role in ('owner','moderator'));$$;
create function orbit_private.platform_mod() returns boolean language sql stable security definer set search_path='' as $$select auth.uid() is not null and exists(select 1 from orbit_private.moderators where actor=auth.uid());$$;
create function orbit_private.can_read(p bigint) returns boolean language sql stable security definer set search_path='' as $$select exists(select 1 from public.orbit_posts post left join public.orbit_circles c on c.id=post.circle where post.id=p and not post.deleted and not orbit_private.blocked(auth.uid(),post.author) and (post.circle is null or (not orbit_private.blocked(auth.uid(),c.owner) and (not c.private or orbit_private.member(c.id)))));$$;
create function orbit_private.lock_pair(a uuid,b uuid) returns void language sql volatile set search_path='' as $$select pg_advisory_xact_lock(hashtextextended(least(a,b)::text||'|'||greatest(a,b)::text,0));$$;
create function orbit_private.rate_actor(u uuid) returns void language plpgsql security definer set search_path='' as $$declare n integer;begin insert into orbit_private.write_limits(actor,bucket,count) values(u,date_trunc('minute',now()),1) on conflict(actor) do update set bucket=excluded.bucket,count=case when write_limits.bucket=excluded.bucket then write_limits.count+1 else 1 end returning count into n;if n>60 then raise exception 'Too many changes. Try again in a minute.';end if;end;$$;
create function orbit_private.notify(recipient uuid,sender uuid,kind text,ref bigint default null) returns void language sql security definer set search_path='' as $$insert into public.orbit_notifications(actor,sender,kind,ref) select recipient,sender,kind,ref where recipient<>sender and not exists(select 1 from public.orbit_blocks where (actor=recipient and target=sender) or (actor=sender and target=recipient));$$;
create function orbit_private.cancel_games(a uuid,b uuid) returns void language sql security definer set search_path='' as $$update public.orbit_games set status='cancelled',game=jsonb_set(jsonb_set(game,'{status}','"cancelled"'),'{updatedAt}',to_jsonb((extract(epoch from now())*1000)::bigint)),version=version+1,updated_at=now() where low_actor=least(a,b) and high_actor=greatest(a,b) and status in ('invited','active');$$;
create function orbit_private.new_user() returns trigger language plpgsql security definer set search_path='' as $$declare h text:=lower(coalesce(new.raw_user_meta_data->>'handle','student_'||substr(replace(new.id::text,'-',''),1,16)));n text;begin if h !~ '^[a-z][a-z0-9_]{2,23}$' then raise exception 'Invalid campus handle.';end if;n:=left(coalesce(nullif(trim(new.raw_user_meta_data->>'displayName'),''),h),80);insert into public.orbit_profiles(id,handle,display_name) values(new.id,h,n);return new;end;$$;
create trigger orbit_new_auth_user after insert on auth.users for each row execute function orbit_private.new_user();
create policy profiles_read on public.orbit_profiles for select to anon,authenticated using(not orbit_private.blocked((select auth.uid()),id));
revoke all on public.orbit_profiles from anon,authenticated;
grant select on public.orbit_profiles to anon,authenticated;
grant all on public.orbit_profiles to service_role;
create policy circles_read on public.orbit_circles for select to anon,authenticated using(not orbit_private.blocked((select auth.uid()),owner));
revoke all on public.orbit_circles from anon,authenticated;
grant select on public.orbit_circles to anon,authenticated;
grant all on public.orbit_circles to service_role;
create policy members_read on public.orbit_members for select to authenticated using(orbit_private.member(circle));
revoke all on public.orbit_members from anon,authenticated;
grant select on public.orbit_members to authenticated;
grant all on public.orbit_members to service_role;
create policy join_requests_read on public.orbit_join_requests for select to authenticated using(actor=(select auth.uid()) or orbit_private.circle_mod(circle));
revoke all on public.orbit_join_requests from anon,authenticated;
grant select on public.orbit_join_requests to authenticated;
grant all on public.orbit_join_requests to service_role;
create policy posts_read on public.orbit_posts for select to anon,authenticated using(orbit_private.can_read(id));
revoke all on public.orbit_posts from anon,authenticated;
grant select on public.orbit_posts to anon,authenticated;
grant all on public.orbit_posts to service_role;
create policy comments_read on public.orbit_comments for select to anon,authenticated using(orbit_private.can_read(post) and not orbit_private.blocked((select auth.uid()),author));
revoke all on public.orbit_comments from anon,authenticated;
grant select on public.orbit_comments to anon,authenticated;
grant all on public.orbit_comments to service_role;
create policy votes_read on public.orbit_votes for select to anon,authenticated using(orbit_private.can_read(post));
revoke all on public.orbit_votes from anon,authenticated;
grant select on public.orbit_votes to anon,authenticated;
grant all on public.orbit_votes to service_role;
create policy follows_read on public.orbit_follows for select to anon,authenticated using(not orbit_private.blocked((select auth.uid()),actor) and not orbit_private.blocked((select auth.uid()),target));
revoke all on public.orbit_follows from anon,authenticated;
grant select on public.orbit_follows to anon,authenticated;
grant all on public.orbit_follows to service_role;
create policy connections_read on public.orbit_connections for select to authenticated using((select auth.uid()) in (sender,recipient) and not orbit_private.blocked(sender,recipient));
revoke all on public.orbit_connections from anon,authenticated;
grant select on public.orbit_connections to authenticated;
grant all on public.orbit_connections to service_role;
create policy blocks_read on public.orbit_blocks for select to authenticated using(actor=(select auth.uid()));
revoke all on public.orbit_blocks from anon,authenticated;
grant select on public.orbit_blocks to authenticated;
grant all on public.orbit_blocks to service_role;
create policy messages_read on public.orbit_messages for select to authenticated using((select auth.uid()) in (sender,recipient) and not orbit_private.blocked(sender,recipient));
revoke all on public.orbit_messages from anon,authenticated;
grant select on public.orbit_messages to authenticated;
grant all on public.orbit_messages to service_role;
create policy games_read on public.orbit_games for select to authenticated using((select auth.uid()) in (low_actor,high_actor) and not orbit_private.blocked(low_actor,high_actor));
revoke all on public.orbit_games from anon,authenticated;
grant select on public.orbit_games to authenticated;
grant all on public.orbit_games to service_role;
create policy notifications_read on public.orbit_notifications for select to authenticated using(actor=(select auth.uid()) and not orbit_private.blocked(actor,sender));
revoke all on public.orbit_notifications from anon,authenticated;
grant select on public.orbit_notifications to authenticated;
grant all on public.orbit_notifications to service_role;
create policy reports_read on public.orbit_reports for select to authenticated using(reporter=(select auth.uid()) or orbit_private.platform_mod());
revoke all on public.orbit_reports from anon,authenticated;
grant select on public.orbit_reports to authenticated;
grant all on public.orbit_reports to service_role;
grant usage,select on all sequences in schema public to service_role;
create function orbit_private.api(path text,method text,body jsonb) returns jsonb language plpgsql security definer set search_path='' as $$
declare u uuid:=auth.uid();peer uuid;parts text[]:=string_to_array(trim(both '/' from path),'/');lim integer:=least(50,greatest(1,coalesce((body->>'limit')::integer,25)));before_id bigint:=coalesce((body->>'before')::bigint,9223372036854775807);pid bigint;cid bigint;rid bigint;rowp public.orbit_posts;rowc public.orbit_comments;circle_row public.orbit_circles;conn public.orbit_connections;result jsonb;val text;exists_vote boolean;begin
 if jsonb_typeof(body)<>'object' or method not in ('GET','POST') then raise exception 'Invalid request.';end if;
 if method='POST' then u:=orbit_private.actor();perform orbit_private.rate_actor(u);end if;
 if path='/me' and method='GET' then select jsonb_build_object('user',case when p.id is null then null else jsonb_build_object('id',p.id,'handle',p.handle,'displayName',p.display_name,'bio',p.bio,'university',p.university,'campus',p.campus,'isModerator',orbit_private.platform_mod()) end) into result from (select u as id) current_user_id left join public.orbit_profiles p using(id);return result;end if;
 if path='/profile' and method='POST' then update public.orbit_profiles set display_name=trim(body->>'displayName'),bio=coalesce(body->>'bio',''),university=coalesce(body->>'university',''),campus=coalesce(body->>'campus','') where id=u;return orbit_private.api('/me','GET','{}')->'user';end if;
 if path='/profiles' and method='GET' then select coalesce(jsonb_agg(to_jsonb(p)),'[]') into result from(select id,handle,display_name as "displayName",bio,university,campus from public.orbit_profiles where (coalesce(body->>'q','')='' or display_name ilike '%'||(body->>'q')||'%' or handle ilike '%'||(body->>'q')||'%') and (coalesce(body->>'campus','')='' or campus=body->>'campus') and not orbit_private.blocked(u,id) order by handle limit lim) p;return jsonb_build_object('items',result);end if;
 if path='/feed' and method='GET' then
 if body->>'circle' is not null and not exists(select 1 from public.orbit_circles where id=(body->>'circle')::bigint and (not private or orbit_private.member(id))) then raise exception 'Circle unavailable.' using errcode='42501';end if;
 select coalesce(jsonb_agg(to_jsonb(p)),'[]') into result from(select post.*,profile.display_name as "displayName",profile.handle from public.orbit_posts post join public.orbit_profiles profile on profile.id=post.author where (body->>'sort' in ('Hot','Top') or post.id<before_id) and orbit_private.can_read(post.id) and (body->>'circle' is null or post.circle=(body->>'circle')::bigint) and (coalesce(body->>'q','')='' or post.title ilike '%'||(body->>'q')||'%' or post.text ilike '%'||(body->>'q')||'%') and (body->>'author' is null or post.author=(body->>'author')::uuid) order by case when body->>'sort'='Hot' then (post.upvotes+post.reply_count+1)/power(greatest(0,extract(epoch from(now()-post.created))/3600)+2,1.5) when body->>'sort'='Top' then post.upvotes::numeric else 0 end desc,post.id desc limit lim offset least(10000,greatest(0,coalesce((body->>'offset')::integer,0)))) p;return jsonb_build_object('items',result,'next',result->-1->'id');end if;
 if path='/posts' and method='POST' then cid:=(body->>'circle')::bigint;if cid is not null then select * into circle_row from public.orbit_circles where id=cid;if circle_row.id is null or not orbit_private.member(cid) or orbit_private.blocked(u,circle_row.owner) then raise exception 'Circle membership required.' using errcode='42501';end if;end if;insert into public.orbit_posts(author,title,text,topic,circle) values(u,trim(body->>'title'),trim(body->>'text'),coalesce(body->>'topic',''),cid) returning id into pid;return jsonb_build_object('id',pid);end if;
 if parts[1]='posts' and array_length(parts,1)>=2 then pid:=parts[2]::bigint;select * into rowp from public.orbit_posts where id=pid;if not orbit_private.can_read(pid) then raise exception 'Post unavailable.' using errcode='42501';end if;
 if array_length(parts,1)=2 and method='POST' then if rowp.author<>u then raise exception 'Only the author can change this post.' using errcode='42501';end if;if body->>'delete'='true' then update public.orbit_posts set title='Deleted post',text='[Deleted]',deleted=true,edited=now() where id=pid;else update public.orbit_posts set title=trim(body->>'title'),text=trim(body->>'text'),edited=now() where id=pid;end if;return '{"ok":true}';end if;
 if parts[3]='comments' and method='GET' then select coalesce(jsonb_agg(to_jsonb(r)),'[]') into result from(select c.*,p.handle from public.orbit_comments c join public.orbit_profiles p on p.id=c.author where c.post=pid and c.id<before_id and not orbit_private.blocked(u,c.author) order by c.id desc limit lim) r;return jsonb_build_object('items',result);end if;
 if parts[3]='comments' and method='POST' then rid:=(body->>'parent')::bigint;if rid is not null and not exists(select 1 from public.orbit_comments where id=rid and post=pid and not deleted and not orbit_private.blocked(u,author)) then raise exception 'Comment unavailable.';end if;insert into public.orbit_comments(post,author,parent,text) values(pid,u,rid,trim(body->>'text')) returning id into rid;update public.orbit_posts set reply_count=reply_count+1 where id=pid;perform orbit_private.notify(rowp.author,u,'reply',pid);return jsonb_build_object('id',rid);end if;
 if parts[3]='vote' and method='POST' then perform pg_advisory_xact_lock(hashtextextended('vote:'||u::text||':'||pid::text,0));exists_vote:=exists(select 1 from public.orbit_votes where post=pid and actor=u);if exists_vote then delete from public.orbit_votes where post=pid and actor=u;else insert into public.orbit_votes values(pid,u);perform orbit_private.notify(rowp.author,u,'upvote',pid);end if;update public.orbit_posts set upvotes=upvotes+case when exists_vote then -1 else 1 end where id=pid returning upvotes into rid;return jsonb_build_object('upvotes',rid);end if;end if;
 if parts[1]='comments' and method='POST' then select * into rowc from public.orbit_comments where id=parts[2]::bigint;if rowc.id is null or rowc.author<>u or rowc.deleted or not orbit_private.can_read(rowc.post) then raise exception 'Only the author can change this comment.' using errcode='42501';end if;if body->>'delete'='true' then update public.orbit_comments set text='[Deleted]',deleted=true,edited=now() where id=rowc.id;update public.orbit_posts set reply_count=greatest(0,reply_count-1) where id=rowc.post;else update public.orbit_comments set text=trim(body->>'text'),edited=now() where id=rowc.id;end if;return '{"ok":true}';end if;
 if parts[1]='people' and array_length(parts,1)=3 then u:=orbit_private.actor();select id into peer from public.orbit_profiles where handle=parts[2];if peer is null or peer=u then raise exception 'Student unavailable.';end if;perform orbit_private.lock_pair(u,peer);
 if parts[3]='block' and method='POST' then if body->>'block'='false' then delete from public.orbit_blocks where actor=u and target=peer;else insert into public.orbit_blocks values(u,peer) on conflict do nothing;update public.orbit_connections set status='removed' where low_actor=least(u,peer) and high_actor=greatest(u,peer);perform orbit_private.cancel_games(u,peer);end if;return '{"ok":true}';end if;
 if orbit_private.blocked(u,peer) then raise exception 'Student unavailable.' using errcode='42501';end if;
 select * into conn from public.orbit_connections where low_actor=least(u,peer) and high_actor=greatest(u,peer);
 if method='GET' then return jsonb_build_object('connection',case when conn.sender is null then null else jsonb_build_object('sender',conn.sender,'recipient',conn.recipient,'status',conn.status) end,'following',exists(select 1 from public.orbit_follows where actor=u and target=peer),'peer',peer);end if;
 if parts[3]='follow' then if exists(select 1 from public.orbit_follows where actor=u and target=peer) then delete from public.orbit_follows where actor=u and target=peer;else insert into public.orbit_follows values(u,peer);perform orbit_private.notify(peer,u,'follow');end if;return '{"ok":true}';end if;
 if parts[3]='connection' then val:=body->>'action';if val='request' then if conn.status in ('pending','accepted') then raise exception 'Connection already exists.';end if;insert into public.orbit_connections(sender,recipient,status) values(u,peer,'pending') on conflict(low_actor,high_actor) do update set sender=excluded.sender,recipient=excluded.recipient,status='pending';perform orbit_private.notify(peer,u,'request');elsif val in ('accept','decline') then if conn.status is distinct from 'pending' or conn.recipient is distinct from u then raise exception 'Only the recipient can respond.' using errcode='42501';end if;update public.orbit_connections set status=case when val='accept' then 'accepted' else 'declined' end where low_actor=least(u,peer) and high_actor=greatest(u,peer);elsif val='remove' then if conn.status is distinct from 'accepted' then raise exception 'Connection unavailable.';end if;update public.orbit_connections set status='removed' where low_actor=least(u,peer) and high_actor=greatest(u,peer);perform orbit_private.cancel_games(u,peer);else raise exception 'Unknown connection action.';end if;return '{"ok":true}';end if;end if;
 if parts[1]='messages' and array_length(parts,1)=2 then u:=orbit_private.actor();select id into peer from public.orbit_profiles where handle=parts[2];if peer is null or peer=u or orbit_private.blocked(u,peer) then raise exception 'Conversation unavailable.' using errcode='42501';end if;
 if method='GET' then select coalesce(jsonb_agg(to_jsonb(m)),'[]') into result from(select m.*,p.handle from public.orbit_messages m join public.orbit_profiles p on p.id=m.sender where m.id<before_id and ((sender=u and recipient=peer) or(sender=peer and recipient=u)) order by m.id desc limit lim) m;return jsonb_build_object('items',result);end if;
 perform orbit_private.lock_pair(u,peer);if not exists(select 1 from public.orbit_connections where low_actor=least(u,peer) and high_actor=greatest(u,peer) and status='accepted') or orbit_private.blocked(u,peer) then raise exception 'An accepted connection is required.' using errcode='42501';end if;insert into public.orbit_messages(sender,recipient,text) values(u,peer,trim(body->>'text')) returning id into rid;perform orbit_private.notify(peer,u,'message',rid);return jsonb_build_object('id',rid);end if;
 if path='/circles' and method='GET' then select coalesce(jsonb_agg(to_jsonb(c)),'[]') into result from(select c.*,(select handle from public.orbit_profiles where id=c.owner) as "ownerHandle",(select role from public.orbit_members where circle=c.id and actor=u) as role from public.orbit_circles c where c.id<before_id and not orbit_private.blocked(u,c.owner) order by c.id desc limit lim)c;return jsonb_build_object('items',result);end if;
 if path='/circles' and method='POST' then insert into public.orbit_circles(title,description,owner,private) values(trim(body->>'title'),trim(body->>'description'),u,coalesce((body->>'private')::boolean,false)) returning id into cid;insert into public.orbit_members values(cid,u,'owner');return jsonb_build_object('id',cid);end if;
 if parts[1]='circles' and array_length(parts,1)=3 then u:=orbit_private.actor();cid:=parts[2]::bigint;select * into circle_row from public.orbit_circles where id=cid;if circle_row.id is null or orbit_private.blocked(u,circle_row.owner) then raise exception 'Circle unavailable.' using errcode='42501';end if;
 if parts[3]='members' and method='GET' then if not orbit_private.member(cid) then raise exception 'Membership required.' using errcode='42501';end if;return jsonb_build_object('members',(select coalesce(jsonb_agg(jsonb_build_object('user',p.handle,'id',m.actor,'role',m.role)),'[]') from public.orbit_members m join public.orbit_profiles p on p.id=m.actor where circle=cid),'requests',case when orbit_private.circle_mod(cid) then(select coalesce(jsonb_agg(jsonb_build_object('user',p.handle,'id',r.actor)),'[]') from public.orbit_join_requests r join public.orbit_profiles p on p.id=r.actor where circle=cid)else '[]'::jsonb end);end if;
 if method='POST' then if parts[3]='join' then if circle_row.private then insert into public.orbit_join_requests values(cid,u) on conflict do nothing;else insert into public.orbit_members values(cid,u,'member') on conflict do nothing;end if;
 elsif parts[3]='review' then if not orbit_private.circle_mod(cid) then raise exception 'Moderator required.' using errcode='42501';end if;select id into peer from public.orbit_profiles where handle=body->>'user';if peer is null or orbit_private.blocked(u,peer) or exists(select 1 from public.orbit_blocks where (actor=peer and target=circle_row.owner) or(actor=circle_row.owner and target=peer)) or not exists(select 1 from public.orbit_join_requests where circle=cid and actor=peer) then raise exception 'Request unavailable.';end if;if body->>'accept'='true' then insert into public.orbit_members values(cid,peer,'member') on conflict do nothing;end if;delete from public.orbit_join_requests where circle=cid and actor=peer;
 elsif parts[3]='moderator' then if circle_row.owner<>u then raise exception 'Owner required.' using errcode='42501';end if;select id into peer from public.orbit_profiles where handle=body->>'user';if peer is null or peer=u or not exists(select 1 from public.orbit_members where circle=cid and actor=peer) then raise exception 'Choose another member.';end if;update public.orbit_members set role=case when body->>'moderator'='true' then 'moderator' else 'member' end where circle=cid and actor=peer;
 elsif parts[3]='settings' then if circle_row.owner<>u then raise exception 'Owner required.' using errcode='42501';end if;update public.orbit_circles set rules=coalesce(body->>'rules',''),private=coalesce((body->>'private')::boolean,false) where id=cid;else raise exception 'Invalid circle action.';end if;return '{"ok":true}';end if;end if;
 if path='/notifications' then u:=orbit_private.actor();if method='POST' then update public.orbit_notifications set read=true where actor=u;return '{"ok":true}';end if;select coalesce(jsonb_agg(to_jsonb(n)),'[]') into result from(select n.*,p.handle from public.orbit_notifications n join public.orbit_profiles p on p.id=n.sender where n.actor=u and n.id<before_id and not orbit_private.blocked(u,n.sender) order by n.id desc limit lim)n;return jsonb_build_object('items',result);end if;
 if path='/reports' then u:=orbit_private.actor();if method='GET' then if not orbit_private.platform_mod() then raise exception 'Moderator required.' using errcode='42501';end if;select coalesce(jsonb_agg(to_jsonb(r)),'[]') into result from(select * from public.orbit_reports where id<before_id order by id desc limit lim)r;return jsonb_build_object('items',result);end if;select id into peer from public.orbit_profiles where handle=body->>'target';if peer is null or peer=u then raise exception 'Student unavailable.';end if;insert into public.orbit_reports(reporter,target,reason,details) values(u,peer,body->>'reason',coalesce(body->>'details',''));return '{"ok":true}';end if;
 if parts[1]='reports' and method='POST' then if not orbit_private.platform_mod() then raise exception 'Moderator required.' using errcode='42501';end if;update public.orbit_reports set status=body->>'status' where id=parts[2]::bigint;return '{"ok":true}';end if;
 raise exception 'Endpoint not found.' using errcode='22023';
end;$$;
create function public.orbit_api(path text,method text default 'GET',body jsonb default '{}') returns jsonb language sql volatile security invoker set search_path='' as $$select orbit_private.api(path,method,body);$$;

-- The verified Edge Function alone can commit games. Clients receive SELECT only.
create function public.orbit_commit_game(p_actor uuid,p_peer uuid,p_game_id bigint,p_expected_version integer,p_payload jsonb,p_status text) returns jsonb language plpgsql security invoker set search_path='' as $$
declare rowg public.orbit_games;begin
 perform orbit_private.lock_pair(p_actor,p_peer);perform orbit_private.rate_actor(p_actor);
 if p_actor=p_peer or not exists(select 1 from public.orbit_connections where low_actor=least(p_actor,p_peer) and high_actor=greatest(p_actor,p_peer) and status='accepted') or exists(select 1 from public.orbit_blocks b where (b.actor=p_actor and b.target=p_peer)or(b.actor=p_peer and b.target=p_actor)) then raise exception 'An accepted connection is required.' using errcode='42501';end if;
 if not(p_payload->'players' @> jsonb_build_array(p_actor,p_peer)) or jsonb_array_length(p_payload->'players')<>2 then raise exception 'Invalid players.';end if;
 if p_game_id is null then update public.orbit_games set status='expired' where low_actor=least(p_actor,p_peer) and high_actor=greatest(p_actor,p_peer) and status in('active','invited') and updated_at<=now()-interval '7 days';insert into public.orbit_games(low_actor,high_actor,game,status) values(least(p_actor,p_peer),greatest(p_actor,p_peer),p_payload,p_status) returning * into rowg;update public.orbit_games set game=jsonb_set(game,'{id}',to_jsonb(rowg.id)) where id=rowg.id returning * into rowg;
 else select * into rowg from public.orbit_games where id=p_game_id and low_actor=least(p_actor,p_peer) and high_actor=greatest(p_actor,p_peer) for update;if rowg.id is null or rowg.version<>p_expected_version then raise exception 'The match changed. Reload before moving.' using errcode='40001';end if;update public.orbit_games set game=p_payload,status=p_status,version=version+1,updated_at=now() where id=p_game_id returning * into rowg;end if;
 perform orbit_private.notify(p_peer,p_actor,'game',rowg.id);return to_jsonb(rowg);
end;$$;
revoke all on all functions in schema orbit_private from public,anon,authenticated;
grant execute on function orbit_private.blocked(uuid,uuid),orbit_private.member(bigint),orbit_private.circle_mod(bigint),orbit_private.platform_mod(),orbit_private.can_read(bigint),orbit_private.api(text,text,jsonb) to anon,authenticated;
revoke all on function public.orbit_api(text,text,jsonb) from public;grant execute on function public.orbit_api(text,text,jsonb) to anon,authenticated;
revoke all on function public.orbit_commit_game(uuid,uuid,bigint,integer,jsonb,text) from public,anon,authenticated;grant execute on function public.orbit_commit_game(uuid,uuid,bigint,integer,jsonb,text) to service_role;
grant execute on all functions in schema orbit_private to service_role;
create index orbit_games_high_actor_idx on public.orbit_games(high_actor);
notify pgrst,'reload schema';
commit;
